import mailbox
from email import policy
from email.parser import BytesParser
from email.utils import parsedate_to_datetime, parseaddr
from pathlib import Path
from .normalize import email as normalize_email
from .sla import due_at
from .timeutil import format_utc


def _body(message):
    if message.is_multipart():
        preferred = message.get_body(preferencelist=("plain",))
        if preferred is not None:
            return preferred.get_content().rstrip("\n")
        return ""
    value = message.get_content()
    return value.rstrip("\n") if isinstance(value, str) else value.decode("utf-8", "replace").rstrip("\n")


def _timestamp(message):
    raw = message.get("Date")
    if not raw: raise ValueError("mbox message is missing Date")
    dt = parsedate_to_datetime(raw)
    if dt is None or dt.tzinfo is None: raise ValueError("mbox Date must include an offset")
    return format_utc(dt)


def import_file(conn, path, priority="normal"):
    if priority not in {"urgent", "normal", "low"}: raise ValueError("invalid priority")
    source = str(Path(path).resolve())
    counts = {"imported": 0, "skipped": 0, "tickets": 0, "comments": 0}
    parser = BytesParser(policy=policy.default)
    box = mailbox.mbox(path, factory=parser.parse, create=False)
    conn.execute("BEGIN IMMEDIATE")
    try:
        for message in box:
            message_id = str(message.get("Message-ID", "")).strip()
            if not message_id: raise ValueError("mbox message is missing Message-ID")
            if conn.execute("SELECT 1 FROM imported_messages WHERE message_id=?", (message_id,)).fetchone():
                counts["skipped"] += 1
                continue
            sender = normalize_email(parseaddr(str(message.get("From", "")))[1])
            created, body = _timestamp(message), _body(message)
            subject = str(message.get("Subject", "(no subject)")) or "(no subject)"
            parent_ids = []
            if message.get("In-Reply-To"): parent_ids.append(str(message["In-Reply-To"]).strip())
            refs = str(message.get("References", "")).split()
            parent_ids.extend(reversed(refs))
            parent = None
            for parent_id in parent_ids:
                parent = conn.execute("SELECT ticket_id FROM imported_messages WHERE message_id=?", (parent_id,)).fetchone()
                if parent: break
            if parent:
                ticket_id = parent["ticket_id"]
                cur = conn.execute("""INSERT INTO comments
                    (ticket_id,author_email,author_type,body,created_at,external_message_id)
                    VALUES (?,?,?,?,?,?)""", (ticket_id, sender, "customer", body, created, message_id))
                comment_id = cur.lastrowid
                state = conn.execute("SELECT status FROM tickets WHERE id=?", (ticket_id,)).fetchone()[0]
                if state in {"resolved", "closed"}:
                    conn.execute("UPDATE tickets SET status='open',updated_at=?,reopened_at=?,closed_at=NULL WHERE id=?",
                                 (created, created, ticket_id))
                counts["comments"] += 1
            else:
                cur = conn.execute("""INSERT INTO tickets
                    (subject,body,status,priority,assignee_id,requester_email,created_at,updated_at,sla_due_at,external_message_id)
                    VALUES (?,?,'open',?,NULL,?,?,?,?,?)""",
                    (subject, body, priority, sender, created, created, due_at(created, priority), message_id))
                ticket_id, comment_id = cur.lastrowid, None
                counts["tickets"] += 1
            conn.execute("INSERT INTO imported_messages(message_id,ticket_id,comment_id,source) VALUES (?,?,?,?)",
                         (message_id, ticket_id, comment_id, source))
            counts["imported"] += 1
        conn.commit()
        return counts
    except BaseException:
        conn.rollback(); raise
    finally:
        box.close()
import argparse
import json
from . import agents, exporter, mail_import, maintenance, server
from .db import connect


def _print(value):
    print(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")), flush=True)


def main(argv=None):
    parser = argparse.ArgumentParser(prog="helpdesk")
    commands = parser.add_subparsers(dest="cmd", required=True)
    serve = commands.add_parser("serve")
    serve.add_argument("--db", required=True); serve.add_argument("--port", type=int, required=True)
    create = commands.add_parser("create-agent")
    create.add_argument("db"); create.add_argument("--email", required=True)
    imp = commands.add_parser("import-mbox")
    imp.add_argument("db"); imp.add_argument("mbox"); imp.add_argument("--priority", default="normal")
    export = commands.add_parser("export")
    export.add_argument("db"); export.add_argument("output")
    for name in ("close-stale", "maintain"):
        stale = commands.add_parser(name)
        stale.add_argument("db"); stale.add_argument("--now", required=True); stale.add_argument("--days", type=int, default=7)
    args = parser.parse_args(argv)
    if args.cmd == "serve":
        server.serve(args.db, args.port)
        return
    conn = connect(args.db)
    try:
        if args.cmd == "create-agent": result = agents.create(conn, args.email)
        elif args.cmd == "import-mbox": result = mail_import.import_file(conn, args.mbox, args.priority)
        elif args.cmd == "export": result = exporter.write_jsonl(conn, args.output)
        else: result = maintenance.close_stale(conn, args.now, args.days)
        _print(result)
    finally:
        conn.close()

